def solve(inputs: dict) -> float:
    n = inputs['n']
    k = inputs['k']
    def josephus(n, k):
        if n == 1:
            return 0
        else:
            return (josephus(n-1, k) + k) % n
    survivor_position = josephus(n, k) + 1
    return float(survivor_position)

